package com.mo.economy_system.network;
import static org.junit.jupiter.api.Assertions.*;import com.mo.economy_system.common.network.*;import com.mo.economy_system.protocol.*;import io.netty.buffer.Unpooled;import io.netty.handler.codec.DecoderException;import java.util.UUID;import net.minecraft.network.FriendlyByteBuf;import org.junit.jupiter.api.Test;
class TerritoryRemovalWireCodecTest{
 @Test void exactGoldenWireAndProtocol(){UUID id=UUID.fromString("00112233-4455-6677-8899-aabbccddeeff");FriendlyByteBuf b=new FriendlyByteBuf(Unpooled.buffer());TerritoryRemovalWireCodec.encode(new RemoveTerritoryMessage(id),b);assertEquals(16,b.readableBytes());byte[] bytes=new byte[16];b.getBytes(0,bytes);assertArrayEquals(new byte[]{0,17,34,51,68,85,102,119,(byte)136,(byte)153,(byte)170,(byte)187,(byte)204,(byte)221,(byte)238,(byte)255},bytes);assertEquals(id,TerritoryRemovalWireCodec.decode(b).territoryId());assertEquals(21,EconomyMessages.REMOVE_TERRITORY.discriminator());assertEquals(EconomyMessageDirection.CLIENT_TO_SERVER,EconomyMessages.REMOVE_TERRITORY.direction());}
 @Test void rejectsTruncationAndTrailing(){FriendlyByteBuf shortBuf=new FriendlyByteBuf(Unpooled.buffer());shortBuf.writeLong(1);assertThrows(DecoderException.class,()->TerritoryRemovalWireCodec.decode(shortBuf));FriendlyByteBuf trailing=new FriendlyByteBuf(Unpooled.buffer());trailing.writeUUID(UUID.randomUUID());trailing.writeByte(1);assertThrows(DecoderException.class,()->TerritoryRemovalWireCodec.decode(trailing));}
}
